package app.farvater.ui.components

import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.graphics.vector.rememberVectorPainter
import androidx.compose.ui.unit.dp
import app.farvater.ui.theme.Ios

enum class OsLogo { IOS, MATERIAL, NOTHING, ORIGIN, HYPER, HARMONY, ONEUI, OXYGEN }

@Composable
fun OsLogoMark(logo: OsLogo, modifier: Modifier = Modifier) {
    val label = Ios.colors.label
    val mark = marks.getValue(logo)
    val vector = remember(logo, label) { mark.vector(logo.name, label) }
    val wide = mark.width / mark.height > 1.5f
    val height = if (wide) minOf(16f, 72f * mark.height / mark.width) else 28f
    Image(
        rememberVectorPainter(vector),
        contentDescription = null,
        modifier = modifier.size((height * mark.width / mark.height).dp, height.dp),
    )
}

private enum class Ink { LABEL, BRAND, WHITE }

private class Part(val path: String, val ink: Ink = Ink.LABEL, val dx: Float = 0f, val dy: Float = 0f, val evenOdd: Boolean = false)

private class Mark(val width: Float, val height: Float, val brand: Color, val parts: List<Part>) {
    fun vector(name: String, label: Color): ImageVector {
        val builder = ImageVector.Builder(name, width.dp, height.dp, width, height)
        for (part in parts) {
            val color = when (part.ink) {
                Ink.LABEL -> label
                Ink.BRAND -> brand
                Ink.WHITE -> Color.White
            }
            builder.addGroup(translationX = part.dx, translationY = part.dy)
            builder.addPath(
                addPathNodes(part.path),
                pathFillType = if (part.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = SolidColor(color),
            )
            builder.clearGroup()
        }
        return builder.build()
    }
}

